/**
 * @param {Function} fn
 * @return {Function}
 */
function memoize(fn) {
    const root = new Map();         // trie root: argument value -> child Map
    const RESULT = Symbol('result'); // private key under which a node stores its cached result

    return function(...args) {
        // Walk (and build) the trie: one level per argument, keyed by === semantics
        let node = root;
        for (const arg of args) {
            if (!node.has(arg)) node.set(arg, new Map());
            node = node.get(arg);
        }
        // has() rather than a truthiness check, so cached falsy/undefined results still hit
        if (node.has(RESULT)) return node.get(RESULT);
        const result = fn.apply(this, args);
        node.set(RESULT, result);
        return result;
    };
}

/**
 * let callCount = 0;
 * const memoizedFn = memoize(function (a, b) {
 *	 callCount += 1;
 *   return a + b;
 * })
 * memoizedFn(2, 3) // 5
 * memoizedFn(2, 3) // 5
 * console.log(callCount) // 1
 */
